"""Direct native M5 GC reducers and genuine closed-clock feature formulas.

The capped source producer binds original raw MBP parts, tick/instrument
metadata, incidents and native XAU M5 parts. This owner consumes the source's
validated 300-second record buckets; it neither loads a prior field registry
nor accepts a minute cache. Missing source observations retain their masks.
"""
from __future__ import annotations

import hashlib
import json

import numpy as np
import pandas as pd

from gx1.contracts import gc_continuous_source_v1 as source
from gx1.features import gc_order_flow_v1 as formulas

SCHEMA_VERSION = 'gx1_gc_native_m5_feature_surfaces_v1'
INTERVAL_NS = 300_000_000_000
MINUTE_NS = 60_000_000_000
TIMEFRAMES = ('M5', 'M15', 'H1', 'H4', 'D1')
NATIVE_NULLABLE_TIMESTAMP_COLUMNS = (
    'observed_first_bucket_start_ns', 'observed_last_bucket_start_ns',
    'observed_book_first_bucket_start_ns', 'observed_book_last_bucket_start_ns',
    'observed_profile_snapshot_available_ns', 'observed_spot_basis_source_available_ns') + tuple(
    prefix + suffix for prefix in ('spot_basis', 'observed_spot_basis') for suffix in
    ('_gc_last_trade_recv_ns', '_gc_first_trade_recv_ns', '_xau_bar_available_ns',
     '_bucket_start_ns', '_bucket_available_ns'))


def _clock(scope):
    origin, end, interval = source.reduction_clock_v1(scope)
    if scope is None or interval != INTERVAL_NS:
        raise ValueError('GC_NATIVE_M5_EXPLICIT_SOURCE_SCOPE_REQUIRED')
    return np.arange(origin, end, interval, dtype=np.int64)


def native_m5_collectors(*, scope, ladder_path, selected, masks, symbol_index, tick_size):
    """Create both actual raw-record callbacks for one outright contract.

    The caller supplies these callbacks to scan_symbol(native_m5_scope=scope).
    Each contract has a distinct ladder path. The source quality owner decides
    masks; no feature or label estimates source validity in this factory.
    """
    starts = _clock(scope)
    selected = np.asarray(selected)
    if selected.shape != starts.shape or np.asarray(masks['volume']).shape != starts.shape:
        raise ValueError('GC_NATIVE_M5_COLLECTOR_SOURCE_AXIS')
    wanted = np.flatnonzero(selected == symbol_index)
    trades = formulas.TradeLadderCollector(ladder_path, selected, masks['volume'], symbol_index,
        tick_size, input_interval_ns=INTERVAL_NS)
    book = formulas.L1FeatureCollectorV2(wanted, tick_size, origin_ns=int(starts[0]),
        include_order_counts=True, include_event_diagnostics=True, include_trusted_trade_stats=True,
        input_interval_ns=INTERVAL_NS)
    def on_batch(data, idx, trusted_trade):
        trades(data, idx, trusted_trade)
        book(data, idx, trusted_trade)
    return {'wanted': wanted, 'trades': trades, 'book': book,
        'on_batch': on_batch, 'on_file_start': book.file_start,
        'input_interval_ns': INTERVAL_NS}


def add_native_m5_basis(surface, native_xau_m5, *, native_m5_trade_metadata, strict=True):
    """Pair GC close with bid/ask midpoint at the identical native M5 endpoint.

    An observed outer-TF candle selects its last admitted GC source bucket
    first. A missing XAU counterpart stays unknown; no earlier pair is sought.
    Age is a duration in minutes, measured from exact source-close nanoseconds.
    """
    if (not isinstance(native_xau_m5, pd.DataFrame)
            or not isinstance(native_xau_m5.index, pd.DatetimeIndex)
            or native_xau_m5.index.tz is None or str(native_xau_m5.index.tz) != 'UTC'
            or not {'bid_close', 'ask_close'}.issubset(native_xau_m5.columns)):
        raise ValueError('GC_NATIVE_M5_BASIS_XAU_SOURCE')
    xau_start = native_xau_m5.index.as_unit('ns').asi8
    if np.any(xau_start % INTERVAL_NS) or np.any(np.diff(xau_start) <= 0):
        raise ValueError('GC_NATIVE_M5_BASIS_XAU_CLOCK')
    bid = native_xau_m5['bid_close'].to_numpy(np.float64)
    ask = native_xau_m5['ask_close'].to_numpy(np.float64)
    mid = (bid + ask) / 2
    xau_valid = np.isfinite(bid) & np.isfinite(ask) & (bid > 0) & (ask >= bid)
    def pair(available, close, valid):
        available = np.asarray(available)
        target_start = np.where(valid, available - INTERVAL_NS, 0).astype(np.int64)
        idx = np.searchsorted(xau_start, target_start)
        known = np.zeros(len(idx), bool)
        value = np.full(len(idx), np.nan)
        inside = np.flatnonzero(valid & (idx < len(xau_start)))
        if len(inside):
            same = xau_start[idx[inside]] == target_start[inside]
            rows = inside[same & xau_valid[idx[inside]] & np.isfinite(close[inside]) & (close[inside] > 0)]
            known[rows] = True
            value[rows] = 10_000 * (close[rows] / mid[idx[rows]] - 1)
        return value, known
    trade_starts = np.asarray(native_m5_trade_metadata['bar_start_ns'])
    first_trade = np.asarray(native_m5_trade_metadata['first_trusted_trade_recv_ns'])
    last_trade = np.asarray(native_m5_trade_metadata['last_trusted_trade_recv_ns'])
    if (trade_starts.dtype != np.int64 or first_trade.dtype != np.int64 or last_trade.dtype != np.int64
            or trade_starts.ndim != 1 or first_trade.shape != trade_starts.shape
            or last_trade.shape != trade_starts.shape or np.any(np.diff(trade_starts) <= 0)
            or np.any(trade_starts % INTERVAL_NS)):
        raise ValueError('GC_NATIVE_M5_BASIS_TRADE_EVENT_AXIS')
    def event_metadata(prefix, source_close, gc_valid, pair_valid):
        target = np.where(gc_valid, source_close - INTERVAL_NS, 0).astype(np.int64)
        idx = np.searchsorted(trade_starts, target)
        rows = np.flatnonzero(gc_valid)
        if np.any(idx[rows] >= len(trade_starts)):
            raise ValueError('GC_NATIVE_M5_BASIS_TRADE_EVENT_MISSING')
        selected = idx[rows]
        if (np.any(trade_starts[selected] != target[rows])
                or np.any(first_trade[selected] < target[rows])
                or np.any(last_trade[selected] < first_trade[selected])
                or np.any(last_trade[selected] >= source_close[rows])):
            raise ValueError('GC_NATIVE_M5_BASIS_TRADE_EVENT_DOMAIN')
        first = np.full(len(target), -1, np.int64);last = first.copy()
        first[rows] = first_trade[selected];last[rows] = last_trade[selected]
        surface[prefix + '_gc_first_trade_recv_ns'] = first
        surface[prefix + '_gc_last_trade_recv_ns'] = last
        surface[prefix + '_gc_event_valid'] = np.asarray(gc_valid, bool).copy()
        surface[prefix + '_gc_trade_age_minutes'] = np.where(gc_valid,
            (surface['available_ns'] - last) / MINUTE_NS, np.nan)
        surface[prefix + '_bucket_start_ns'] = np.where(gc_valid, target, -1)
        surface[prefix + '_bucket_available_ns'] = np.where(gc_valid, source_close, -1)
        surface[prefix + '_xau_bar_available_ns'] = np.where(pair_valid, source_close, -1)

    observed = np.asarray(surface['observed_valid'], bool)
    last = np.asarray(surface['observed_last_bucket_start_ns'])
    source_close = np.where(observed, last + INTERVAL_NS, -1).astype(np.int64)
    values, known = pair(source_close, np.asarray(surface['observed_close_usd']), observed)
    surface['observed_spot_basis_bps'] = values
    surface['observed_spot_basis_valid'] = known
    # Integer metadata has its explicit nullable-domain gate; the publisher must
    # write nulls wherever known=False rather than serialize the storage sentinel.
    surface['observed_spot_basis_source_available_ns'] = np.where(known, source_close, -1)
    event_metadata('observed_spot_basis', source_close, observed, known)
    surface['observed_spot_basis_age_minutes'] = np.where(known,
        (surface['available_ns'] - source_close) / MINUTE_NS, np.nan)
    if strict:
        values, known = pair(surface['available_ns'], np.asarray(surface['close_usd']),
                             np.asarray(surface['volume_valid'], bool))
        surface['spot_basis_bps'] = values
        surface['spot_basis_valid'] = known
        event_metadata('spot_basis', np.asarray(surface['available_ns']),
                       np.asarray(surface['volume_valid'], bool), known)
    return surface


def build_native_m5_gc_surfaces(*, scope, selected, metrics, masks, ohlc, ladder_path,
        book, events, trade_stats, tick_size, native_xau_m5, first_trusted_trade_recv_ns,
        last_trusted_trade_recv_ns, profile_state_max_bytes=None):
    """Apply every existing GC formula family to direct native5 observations.

    All arrays address the exact declared native source grid. Input book/event
    and trade-size arrays are the merged outputs of the per-contract callbacks
    above, gated by the independent source quality owner. The caller retains
    original raw provenance and publishes arrays with their explicit masks.
    """
    starts = _clock(scope)
    selected = np.asarray(selected)
    if (selected.shape != starts.shape or selected.dtype.kind not in 'iu'
            or np.asarray(ohlc).shape != (len(starts), 4)
            or any(np.asarray(value).shape != starts.shape
                   for group in (metrics, masks, book, events, trade_stats) for value in group.values())):
        raise ValueError('GC_NATIVE_M5_FEATURE_SOURCE_AXIS')
    trade_metadata = {'bar_start_ns': starts,
        'first_trusted_trade_recv_ns': np.asarray(first_trusted_trade_recv_ns),
        'last_trusted_trade_recv_ns': np.asarray(last_trusted_trade_recv_ns)}
    surfaces = {}; maps = {}
    for tf in TIMEFRAMES:
        surfaces[tf], maps[tf] = formulas.timeframe_skeleton(starts, selected, metrics, masks,
            ohlc, tf, tick_size, input_interval_ns=INTERVAL_NS)
    observed_profiles = formulas.dynamic_profile_arrays_v2(surfaces['M5']['bar_start_ns'])
    strict_profiles = formulas.dynamic_profile_arrays_v2(surfaces['M5']['bar_start_ns'])
    proof = formulas.consume_ladder(ladder_path, surfaces, maps, tick_size,
        profile_output=observed_profiles, strict_profile_output=strict_profiles,
        profile_state_max_bytes=profile_state_max_bytes, input_interval_ns=INTERVAL_NS)
    cvd = formulas.relative_cvd(starts, selected, masks, metrics, input_interval_ns=INTERVAL_NS)
    known = formulas.known_cumulative_contributions_v1(starts, selected, masks, metrics,
                                                    input_interval_ns=INTERVAL_NS)
    for tf, surface in surfaces.items():
        formulas.add_structure_and_cvd(surface, cvd, maps[tf], starts, input_interval_ns=INTERVAL_NS)
        formulas.add_observed_structure(surface, input_interval_ns=INTERVAL_NS)
        formulas.add_known_cumulative_contributions_v1(surface, known, starts, input_interval_ns=INTERVAL_NS)
        surface.update(formulas.aggregate_observed_book_v1(starts, selected, book, tf,
                                                         input_interval_ns=INTERVAL_NS))
        surface.update(formulas.aggregate_observed_event_diagnostics_v1(starts, selected, events, tf,
                                                                      input_interval_ns=INTERVAL_NS))
        surface.update(formulas.aggregate_observed_trade_size_v1(starts, selected, metrics, masks,
                                                               trade_stats, tf, input_interval_ns=INTERVAL_NS))
        formulas.add_projected_m5_profiles_v2(surface, surfaces['M5']['available_ns'], observed_profiles,
                                            surfaces['M5']['observed_coverage_fraction'])
        add_native_m5_basis(surface, native_xau_m5, native_m5_trade_metadata=trade_metadata)
        for name in NATIVE_NULLABLE_TIMESTAMP_COLUMNS:
            values = np.asarray(surface[name])
            timestamp_known = np.isfinite(values) & (values >= 0)
            if np.any(values[timestamp_known] != values[timestamp_known].astype(np.int64)):
                raise ValueError('GC_NATIVE_M5_TIMESTAMP_INTEGER:' + name)
            surface[name] = np.where(timestamp_known, values, -1).astype(np.int64)
    # Strict M5 book/profile formulas are separate genuine source domains, not
    # aliases for conditionally observed higher-TF values.
    m5_book = {name: np.asarray(book[name]).copy() for name in
        formulas.L1_FIELDS_V2 + formulas.L1_ORDER_COUNT_FIELDS_V1 +
        ('ofi_valid', 'bbo_valid', 'order_count_valid')}
    m5_book.update(strict_profiles)
    m5_book.update(bar_start_ns=starts.copy(), available_ns=starts + INTERVAL_NS,
                   close_usd=np.asarray(surfaces['M5']['close_usd']).copy())
    # A final partial higher-TF bucket cannot publish a future available clock.
    for tf, surface in surfaces.items():
        closed = ((surface['available_ns'] <= scope['end_ns'])
                  & (surface['available_ns'] < source.timing.WINDOW_END_NS))
        surfaces[tf] = {name: np.asarray(value)[closed] for name, value in surface.items()}
    m5_closed = m5_book['available_ns'] < source.timing.WINDOW_END_NS
    m5_book = {name: np.asarray(value)[m5_closed] for name, value in m5_book.items()}
    return {'schema_version': SCHEMA_VERSION, 'source_clock': dict(scope),
        'input_interval_ns': INTERVAL_NS, 'timeframes': surfaces, 'm5_book_features': m5_book,
        'candidate_map': formulas.completion_native_candidates_v1(input_interval_ns=INTERVAL_NS),
        'profile_memory_proof': proof,
        'source_scope': 'direct_raw_MBP_native_M5_and_exact_native_XAU_M5_no_minute_intermediate',
        'native_training_admitted': False}


