# Boolean domains proved by the existing producer formulas, including flags
# historically stored as float by the SMC replay. Numeric sample variation is
# never a domain declaration.
NATIVE_BOOLEAN_SOURCE_COLUMNS = frozenset((
    'ofi_valid', 'bbo_valid', 'order_count_valid', 'volume_valid', 'signed_valid',
    'rolling15_valid', 'rolling60_valid', 'anchored_segment_valid',
    'session_observed_valid', 'session_complete_valid',
    'observed_profile_rolling15_valid', 'observed_profile_rolling60_valid',
    'observed_profile_anchored_segment_valid', 'observed_profile_session_observed_valid',
    'observed_profile_session_complete_valid', 'observed_book_response_contiguous',
    'ob_bull_input_valid', 'ob_bear_input_valid',
    'observed_proxy_ob_bull_input_valid', 'observed_proxy_ob_bear_input_valid',
))


def native_m5_field_catalog():
    """Independent ordered model/source/domain map for the native5 producer."""
    fields = []
    for name, group, tf, column, owner, gate, clock, transform, structural, binary in NATIVE_FIELD_SOURCES:
        fields.append({'name': name, 'availability_field': name + '_observed',
            'packet_group': group, 'timeframe': tf, 'column': column, 'owner': owner,
            'validity_column': gate, 'source_clock_column': clock, 'transform': transform,
            'structural_mask_value': structural,
            'binary_value': structural or binary or column in NATIVE_BOOLEAN_SOURCE_COLUMNS})
    # Five historical support concepts have new native bucket endpoints. Their
    # gates are the existing structural BBO-valid values, without padding masks.
    for tf in TIMEFRAMES:
        fields.append({'name': 'gc_' + tf.lower() + '_observed_book_trailing_support_gap_minutes',
            'availability_field': 'gc_' + tf.lower() + '_observed_book_valid',
            'packet_group': 'timeframes', 'timeframe': tf,
            'column': 'observed_book_last_bucket_start_ns',
            'owner': 'momentum_flow_encoder', 'validity_column': 'observed_book_valid',
            'source_clock_column': 'available_ns', 'transform': 'native_m5_trailing_support_gap_minutes',
            'structural_mask_value': False, 'binary_value': False})
    names = [name for field in fields[:1205] for name in (field['name'], field['availability_field'])]
    names += [field['name'] for field in fields[1205:]]
    if len(set(names)) != len(names) or len(names) != 2415:
        raise RuntimeError('GC_NATIVE_M5_FIELD_INVENTORY')
    payload = {'schema_version': 'gx1_gc_native_m5_field_catalog_v1',
        'source_clock_contract': 'native_m5_and_closed_higher_no_m1_v1',
        'timeframes': list(TIMEFRAMES), 'fields': fields, 'field_names': names,
        'base_value_fields': 1205, 'additional_native_support_values': 5,
        'source_interval_ns': INTERVAL_NS,
        'source_timestamp_storage': 'int64_with_explicit_validity_and_null_on_publish'}
    return {**payload, 'contract_sha256': hashlib.sha256(json.dumps(payload,
        sort_keys=True, separators=(',', ':'), allow_nan=False).encode()).hexdigest()}


def require_native_m5_field_catalog(value):
    if (not isinstance(value, dict)
            or value.get('schema_version') != 'gx1_gc_native_m5_field_catalog_v1'
            or value.get('source_clock_contract') != 'native_m5_and_closed_higher_no_m1_v1'
            or value != native_m5_field_catalog()):
        raise ValueError('GC_NATIVE_M5_FIELD_CATALOG_CONTRACT')
    return json.loads(json.dumps(value))


def source_coverage_report(packet):
    """Check every actual source column/domain; never equate presence with support."""
    if packet.get('schema_version') != SCHEMA_VERSION or packet.get('input_interval_ns') != INTERVAL_NS:
        raise ValueError('GC_NATIVE_M5_FIELD_SOURCE_PACKET')
    _clock(packet['source_clock'])
    report = {}
    undeclared_booleans = []
    for field in native_m5_field_catalog()['fields']:
        table = (packet['m5_book_features'] if field['packet_group'] == 'm5_book_features'
                 else packet['timeframes'][field['timeframe']])
        required = {field['column'], field['source_clock_column'], 'available_ns'}
        if field['validity_column']:required.add(field['validity_column'])
        missing = required - set(table)
        if missing:
            raise RuntimeError('GC_NATIVE_M5_DECLARED_COLUMN_MISSING:' + field['name'] + ':' + ','.join(sorted(missing)))
        values = np.asarray(table[field['column']])
        available = np.asarray(table['available_ns'])
        source_clock = np.asarray(table[field['source_clock_column']])
        if values.shape != available.shape or source_clock.shape != available.shape:
            raise ValueError('GC_NATIVE_M5_DECLARED_COLUMN_AXIS:' + field['name'])
        if values.dtype.kind == 'b' and not field['binary_value']:
            undeclared_booleans.append(field['name'])
        observed = np.isfinite(values) & np.isfinite(source_clock) & (source_clock >= 0)
        if field['validity_column']:
            gate = np.asarray(table[field['validity_column']])
            if gate.shape != available.shape or not np.isin(gate, (0,1)).all():
                raise ValueError('GC_NATIVE_M5_DECLARED_GATE_DOMAIN:' + field['name'])
            observed &= gate.astype(bool)
        if np.any(source_clock[observed] > available[observed]):
            raise ValueError('GC_NATIVE_M5_DECLARED_FUTURE_SOURCE:' + field['name'])
        if field['binary_value'] and not np.isin(values[observed], (0,1)).all():
            raise ValueError('GC_NATIVE_M5_DECLARED_BINARY_DOMAIN:' + field['name'])
        report[field['name']] = {'rows':len(values), 'finite_observed':int(observed.sum()),
            'unknown':int((~observed).sum()), 'source_columns_present':True,
            'packet_group':field['packet_group'], 'timeframe':field['timeframe']}
    return {'schema_version':'gx1_gc_native_m5_field_source_coverage_v1',
        'catalog_contract_sha256':native_m5_field_catalog()['contract_sha256'],
        'base_value_fields':1205,'native_support_values':5,'fields':report,
        'source_boolean_fields_without_binary_declaration':undeclared_booleans,
        'all_declared_source_columns_present':True,
        'physical_support_proven':False,'model_consumption_proven':False}
